        273.0,
        Attributes.of(WIDGET_SHAPE, computeWidgetShape(), WIDGET_COLOR, computeWidgetColor()));

    // 属性とコンテキストを持つ測定値を記録。
    // ほとんどのユーザーは、デフォルトのContext.current()を好んで、コンテキスト引数を省略することを選択します。
    gauge.set(1L, WIDGET_RED_CIRCLE, customContext());
